using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Tool implementations ---------------------------------------------------

/// <summary>Provides web-search and note-taking tools for the research agent.</summary>
static class ResearchTools
{
    private static readonly List<string> s_notes = [];
    private static readonly HttpClient s_http = new();

    [Description("Search the web for a query and return a list of result snippets. Use this to find information about a topic.")]
    public static async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  🔍 Searching: {query}");
        Console.ResetColor();

        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://lite.duckduckgo.com/lite/?q={encoded}";
            var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.UserAgent.ParseAdd("ResearchAgent/1.0");

            var response = await s_http.SendAsync(request);
            response.EnsureSuccessStatusCode();
            var html = await response.Content.ReadAsStringAsync();

            // Extract text snippets from the lite HTML results.
            var snippets = ParseSnippets(html);
            if (snippets.Count == 0)
                return "No results found. Try a different query.";

            var sb = new StringBuilder();
            for (var i = 0; i < Math.Min(snippets.Count, 8); i++)
                sb.AppendLine($"[{i + 1}] {snippets[i]}");

            return sb.ToString();
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try rephrasing the query.";
        }
    }

    [Description("Save a research note. Use this to record important facts, findings, or quotes discovered during research.")]
    public static string SaveNote(
        [Description("The note content to save")] string note)
    {
        s_notes.Add(note);
        Console.ForegroundColor = ConsoleColor.DarkCyan;
        Console.WriteLine($"  📝 Note #{s_notes.Count} saved");
        Console.ResetColor();
        return $"Note #{s_notes.Count} saved successfully.";
    }

    [Description("Retrieve all saved research notes collected so far.")]
    public static string GetNotes()
    {
        if (s_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        for (var i = 0; i < s_notes.Count; i++)
            sb.AppendLine($"[Note {i + 1}] {s_notes[i]}");
        return sb.ToString();
    }

    public static void ClearNotes() => s_notes.Clear();

    // Minimal HTML-snippet parser for DuckDuckGo Lite results.
    private static List<string> ParseSnippets(string html)
    {
        var results = new List<string>();
        // DuckDuckGo Lite wraps each result snippet in a <td> with class "result-snippet".
        const string marker = "class=\"result-snippet\"";
        var idx = 0;
        while ((idx = html.IndexOf(marker, idx, StringComparison.Ordinal)) >= 0)
        {
            var start = html.IndexOf('>', idx) + 1;
            if (start <= 0) break;
            var end = html.IndexOf("</td>", start, StringComparison.Ordinal);
            if (end < 0) break;
            var snippet = html[start..end]
                .Replace("<b>", "").Replace("</b>", "")
                .Replace("<a ", " ").Replace("</a>", "")
                .Replace("&amp;", "&").Replace("&quot;", "\"")
                .Replace("&#x27;", "'").Replace("&lt;", "<").Replace("&gt;", ">")
                .Trim();
            // Strip remaining HTML tags.
            snippet = System.Text.RegularExpressions.Regex.Replace(snippet, "<[^>]+>", "");
            if (!string.IsNullOrWhiteSpace(snippet))
                results.Add(snippet);
            idx = end;
        }
        return results;
    }
}

// --- Main entry point -------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY");
var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT");
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

if (string.IsNullOrEmpty(apiKey))
{
    Console.Error.WriteLine("Error: Set OPENAI_API_KEY (or AZURE_OPENAI_API_KEY + AZURE_OPENAI_ENDPOINT) environment variable.");
    return 1;
}

// Build the chat client with automatic function-calling support.
IChatClient chatClient;
if (!string.IsNullOrEmpty(endpoint))
{
    // Azure OpenAI
    var azureClient = new Azure.AI.OpenAI.AzureOpenAIClient(
        new Uri(endpoint),
        new System.ClientModel.ApiKeyCredential(apiKey));
    chatClient = azureClient.GetChatClient(model).AsIChatClient();
}
else
{
    var openAiClient = new OpenAIClient(apiKey);
    chatClient = openAiClient.GetChatClient(model).AsIChatClient();
}

// Wrap with automatic function invocation so the model can call our tools.
chatClient = new ChatClientBuilder(chatClient)
    .UseFunctionInvocation()
    .Build();

var tools = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(ResearchTools.SearchWeb),
        AIFunctionFactory.Create(ResearchTools.SaveNote),
        AIFunctionFactory.Create(ResearchTools.GetNotes),
    ],
    Temperature = 0.3f,
};

Console.WriteLine("╔════════════════════════════════════════╗");
Console.WriteLine("║        🔬  Research Agent  🔬          ║");
Console.WriteLine("╠════════════════════════════════════════╣");
Console.WriteLine("║  Enter a topic to research, or        ║");
Console.WriteLine("║  type 'quit' to exit.                 ║");
Console.WriteLine("╚════════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Green;
    Console.Write("Topic> ");
    Console.ResetColor();
    var topic = Console.ReadLine()?.Trim();

    if (string.IsNullOrEmpty(topic))
        continue;
    if (topic.Equals("quit", StringComparison.OrdinalIgnoreCase) ||
        topic.Equals("exit", StringComparison.OrdinalIgnoreCase))
        break;

    ResearchTools.ClearNotes();

    var systemPrompt = """
        You are a research assistant. Your job is to research the given topic thoroughly.

        Follow this process:
        1. Search the web for relevant information using multiple varied queries (at least 2-3 searches).
        2. As you find important facts, save them as notes using the SaveNote tool.
        3. After gathering enough information, retrieve your notes with GetNotes.
        4. Produce a well-structured summary of your findings with sections and key takeaways.

        Be thorough but concise. Cite specific facts and figures when available.
        """;

    var messages = new List<ChatMessage>
    {
        new(ChatRole.System, systemPrompt),
        new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
    };

    Console.WriteLine();
    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("Researching...");
    Console.ResetColor();

    try
    {
        var response = await chatClient.GetResponseAsync(messages, tools);

        Console.WriteLine();
        Console.ForegroundColor = ConsoleColor.White;
        Console.WriteLine("═══════════════ Research Summary ═══════════════");
        Console.ResetColor();
        Console.WriteLine(response.Text);
        Console.WriteLine("════════════════════════════════════════════════");
        Console.WriteLine();
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.Error.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }
}

return 0;

